CREATE TABLE IF NOT EXISTS calendar_years(school_id TEXT NOT NULL,year INTEGER NOT NULL,revision INTEGER NOT NULL,released INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL,data_json TEXT NOT NULL,PRIMARY KEY(school_id,year));
CREATE TABLE IF NOT EXISTS calendar_events(school_id TEXT NOT NULL,event_id TEXT NOT NULL,year INTEGER NOT NULL,revision INTEGER NOT NULL,status TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,deleted_at TEXT,data_json TEXT NOT NULL,PRIMARY KEY(school_id,event_id));
CREATE INDEX IF NOT EXISTS calendar_events_window ON calendar_events(school_id,year,start_date,end_date,status);
CREATE TABLE IF NOT EXISTS calendar_metadata(school_id TEXT NOT NULL,kind TEXT NOT NULL,record_id TEXT NOT NULL,year INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL,data_json TEXT NOT NULL,PRIMARY KEY(school_id,kind,record_id));
CREATE INDEX IF NOT EXISTS calendar_metadata_year ON calendar_metadata(school_id,kind,year);
CREATE TABLE IF NOT EXISTS calendar_publications(school_id TEXT NOT NULL,publication_id TEXT NOT NULL,year INTEGER NOT NULL,revision INTEGER NOT NULL,created_at INTEGER NOT NULL,digest TEXT NOT NULL,data_json TEXT NOT NULL,PRIMARY KEY(school_id,publication_id),UNIQUE(school_id,year,revision));
CREATE TABLE IF NOT EXISTS calendar_sync(school_id TEXT NOT NULL,target TEXT NOT NULL,event_id TEXT NOT NULL,desired_revision INTEGER NOT NULL,state TEXT NOT NULL,remote_id TEXT NOT NULL,intent_id TEXT NOT NULL,tombstone INTEGER NOT NULL DEFAULT 0,attempt INTEGER NOT NULL DEFAULT 0,last_error TEXT,next_at INTEGER NOT NULL,data_json TEXT NOT NULL,PRIMARY KEY(school_id,target,event_id));
CREATE INDEX IF NOT EXISTS calendar_sync_due ON calendar_sync(state,next_at,school_id);
CREATE TABLE IF NOT EXISTS calendar_previews(school_id TEXT NOT NULL,preview_id TEXT NOT NULL,actor_id TEXT NOT NULL,kind TEXT NOT NULL,digest TEXT NOT NULL,expires_at INTEGER NOT NULL,data_json TEXT NOT NULL,PRIMARY KEY(school_id,preview_id));
CREATE TABLE IF NOT EXISTS calendar_dispatch_locks(school_id TEXT NOT NULL,target TEXT NOT NULL,event_id TEXT NOT NULL,intent_id TEXT NOT NULL,state TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(school_id,target,event_id));
CREATE TABLE IF NOT EXISTS calendar_exports(school_id TEXT NOT NULL,export_id TEXT NOT NULL,artifact_key TEXT NOT NULL,digest TEXT NOT NULL,provider_id TEXT NOT NULL,state TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(school_id,export_id));
CREATE TABLE IF NOT EXISTS calendar_birthday_pending(school_id TEXT NOT NULL,year INTEGER NOT NULL,event_id TEXT NOT NULL,contacts_revision TEXT NOT NULL,data_json TEXT,deleted INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(school_id,year,event_id));
CREATE TABLE IF NOT EXISTS calendar_birthday_heads(school_id TEXT NOT NULL,year INTEGER NOT NULL,source_sequence INTEGER NOT NULL,contacts_revision TEXT NOT NULL,event_id TEXT NOT NULL,PRIMARY KEY(school_id,year));
CREATE TABLE IF NOT EXISTS calendar_sync_runs(school_id TEXT NOT NULL,run_id TEXT NOT NULL,actor_id TEXT NOT NULL,year INTEGER NOT NULL,target TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(school_id,run_id));
CREATE TABLE IF NOT EXISTS calendar_sync_run_items(school_id TEXT NOT NULL,run_id TEXT NOT NULL,job_id TEXT NOT NULL,target TEXT NOT NULL,event_id TEXT NOT NULL,tombstone INTEGER NOT NULL,PRIMARY KEY(school_id,run_id,job_id));
